  staff_home_first_job: { en: 'Start here. Next time, this opens on the job you do most.', es: 'Empieza aqu\u00ed. La pr\u00f3xima vez se abrir\u00e1 en lo que m\u00e1s haces.', pt: 'Comece aqui. Da pr\u00f3xima vez, isto abre no que voc\u00ea mais faz.', id: 'Mulai di sini. Lain kali, ini terbuka pada tugas yang paling sering Anda lakukan.' },
  staff_home_loading: { en: 'Working out what you need to do next\u2026', es: 'Viendo qu\u00e9 te toca hacer ahora\u2026', pt: 'Vendo o que voc\u00ea precisa fazer agora\u2026', id: 'Menyiapkan tugas Anda berikutnya\u2026' },
  staff_quick_heading: { en: 'Put up Sunday\u2019s notes for {congregation}', es: 'Sube las notas del domingo para {congregation}', pt: 'Coloque as notas de domingo para {congregation}', id: 'Pasang catatan hari Minggu untuk {congregation}' },
  staff_quick_why_stale: { en: 'The page still shows last week\u2019s message.', es: 'La p\u00e1gina todav\u00eda muestra el mensaje de la semana pasada.', pt: 'A p\u00e1gina ainda mostra a mensagem da semana passada.', id: 'Halaman masih menampilkan pesan minggu lalu.' },
  staff_quick_why_replace: { en: 'This replaces {title}, which is up for Sunday now.', es: 'Esto reemplaza {title}, que ya est\u00e1 publicado para el domingo.', pt: 'Isto substitui {title}, que j\u00e1 est\u00e1 no ar para domingo.', id: 'Ini menggantikan {title}, yang sudah tayang untuk hari Minggu.' },
  staff_quick_why_none: { en: 'Nothing is on the page for Sunday yet.', es: 'Todav\u00eda no hay nada en la p\u00e1gina para el domingo.', pt: 'Ainda n\u00e3o h\u00e1 nada na p\u00e1gina para domingo.', id: 'Belum ada apa pun di halaman untuk hari Minggu.' },
  staff_quick_up: { en: 'Sunday\u2019s notes for {congregation} are up: {title}', es: 'Las notas del domingo para {congregation} ya est\u00e1n publicadas: {title}', pt: 'As notas de domingo para {congregation} j\u00e1 est\u00e3o no ar: {title}', id: 'Catatan hari Minggu untuk {congregation} sudah tayang: {title}' },
  staff_quick_other_version: { en: 'Put up a different version', es: 'Subir otra versi\u00f3n', pt: 'Colocar outra vers\u00e3o', id: 'Pasang versi lain' },
  staff_quick_box: { en: 'Paste Sunday\u2019s notes or the YouTube link.', es: 'Pega las notas del domingo o el enlace de YouTube.', pt: 'Cole as notas de domingo ou o link do YouTube.', id: 'Tempel catatan hari Minggu atau tautan YouTube.' },
  staff_quick_box_hint: { en: 'Whatever you have is fine. The app works out the date, title, speaker, series and key verse.', es: 'Lo que tengas est\u00e1 bien. La app calcula la fecha, el t\u00edtulo, qui\u00e9n predica, la serie y el vers\u00edculo clave.', pt: 'O que voc\u00ea tiver serve. O app descobre a data, o t\u00edtulo, quem prega, a s\u00e9rie e o vers\u00edculo-chave.', id: 'Apa pun yang Anda punya sudah cukup. Aplikasi menentukan tanggal, judul, pembicara, seri, dan ayat kunci.' },
