  staff_quick_publishing: { en: 'Putting it on the page\u2026', es: 'Public\u00e1ndolo en la p\u00e1gina\u2026', pt: 'Colocando na p\u00e1gina\u2026', id: 'Memasang di halaman\u2026' },
  staff_quick_not_live_yet: { en: 'This is a preview. Nothing is on the congregation page until you tap the button.', es: 'Esto es una vista previa. Nada aparece en la p\u00e1gina de la congregaci\u00f3n hasta que toques el bot\u00f3n.', pt: 'Isto \u00e9 uma pr\u00e9via. Nada vai para a p\u00e1gina da congrega\u00e7\u00e3o at\u00e9 voc\u00ea tocar no bot\u00e3o.', id: 'Ini pratinjau. Tidak ada yang tayang di halaman jemaat sampai Anda mengetuk tombol.' },
