  staff_quick_done_unverified: { en: 'Saved. The page has not shown it yet: open it and pull to refresh.', es: 'Guardado. La p\u00e1gina todav\u00eda no lo muestra: \u00e1brela y desliza para actualizar.', pt: 'Salvo. A p\u00e1gina ainda n\u00e3o mostrou: abra e puxe para atualizar.', id: 'Tersimpan. Halaman belum menampilkannya: buka dan tarik untuk menyegarkan.' },
  staff_quick_done_empty_attached: { en: 'The video is saved on {title}. The congregation page shows no message right now.', es: 'El video est\u00e1 guardado en {title}. La p\u00e1gina de la congregaci\u00f3n no muestra ning\u00fan mensaje en este momento.', pt: 'O v\u00eddeo est\u00e1 salvo em {title}. A p\u00e1gina da congrega\u00e7\u00e3o n\u00e3o mostra nenhuma mensagem no momento.', id: 'Video tersimpan di {title}. Halaman jemaat tidak menampilkan pesan apa pun saat ini.' },
  staff_quick_err_media_off: { en: 'A link on its own needs the media form\u2019s message and YouTube questions. Ask an admin to switch them back on in History, Ask this again.', es: 'Un enlace solo necesita las preguntas de mensaje y de YouTube del formulario de medios. Pide a un administrador que las vuelva a activar en History, Vuelve a preguntar esto.', pt: 'Um link sozinho precisa das perguntas de mensagem e de YouTube do formul\u00e1rio de m\u00eddia. Pe\u00e7a a um administrador para reativ\u00e1-las em History, Pergunte isto de novo.', id: 'Tautan saja memerlukan pertanyaan pesan dan YouTube di formulir media. Minta admin mengaktifkannya lagi di History, Tanyakan ini lagi.' },
  staff_quick_err_target_gone: { en: 'That message is no longer on the list. Tap Change details and pick the message.', es: 'Ese mensaje ya no est\u00e1 en la lista. Toca Cambiar detalles y elige el mensaje.', pt: 'Essa mensagem n\u00e3o est\u00e1 mais na lista. Toque em Alterar detalhes e escolha a mensagem.', id: 'Pesan itu sudah tidak ada di daftar. Ketuk Ubah detail lalu pilih pesannya.' },
