  pastor_not_staff: { en: 'That email is not on the staff list. Use your @futures.church address.', es: 'Ese correo no est\u00e1 en la lista del equipo. Usa tu direcci\u00f3n @futures.church.', pt: 'Esse e-mail n\u00e3o est\u00e1 na lista da equipe. Use seu endere\u00e7o @futures.church.', id: 'Email itu tidak ada di daftar staf. Gunakan alamat @futures.church Anda.' },
  pastor_passwords_mismatch: { en: 'Passwords do not match.', es: 'Las contrase\u00f1as no coinciden.', pt: 'As senhas n\u00e3o coincidem.', id: 'Kata sandi tidak cocok.' },
  pastor_switch_notice: { en: 'This device is signed in as {email}. Signing in as pastor switches it to your staff email, and the notes on this device go with you.', es: 'Este dispositivo tiene la sesi\u00f3n de {email}. Al iniciar como pastor cambiar\u00e1 a tu correo del equipo, y las notas de este dispositivo ir\u00e1n contigo.', pt: 'Este dispositivo est\u00e1 conectado como {email}. Entrar como pastor muda para seu e-mail da equipe, e as notas deste dispositivo v\u00e3o com voc\u00ea.', id: 'Perangkat ini masuk sebagai {email}. Masuk sebagai pendeta akan beralih ke email staf Anda, dan catatan di perangkat ini ikut bersama Anda.' },
  pastor_offline_error: { en: 'Could not reach the server. Check your connection and try again.', es: 'No se pudo conectar con el servidor. Revisa tu conexi\u00f3n e int\u00e9ntalo de nuevo.', pt: 'N\u00e3o foi poss\u00edvel conectar ao servidor. Verifique sua conex\u00e3o e tente novamente.', id: 'Tidak dapat menghubungi server. Periksa koneksi Anda dan coba lagi.' },
  pastor_unavailable: { en: 'Sign-in is unavailable right now. Try again shortly.', es: 'El inicio de sesi\u00f3n no est\u00e1 disponible en este momento. Int\u00e9ntalo de nuevo en breve.', pt: 'O in\u00edcio de sess\u00e3o n\u00e3o est\u00e1 dispon\u00edvel agora. Tente novamente em breve.', id: 'Masuk tidak tersedia saat ini. Coba lagi sebentar.' },
  pastor_too_many_attempts: { en: 'Too many attempts. Try again later.', es: 'Demasiados intentos. Int\u00e9ntalo de nuevo m\u00e1s tarde.', pt: 'Muitas tentativas. Tente novamente mais tarde.', id: 'Terlalu banyak percobaan. Coba lagi nanti.' },
  pastor_code_refused: { en: 'That code did not work. Check it, or email yourself a new one.', es: 'Ese c\u00f3digo no funcion\u00f3. Rev\u00edsalo o env\u00edate uno nuevo por correo.', pt: 'Esse c\u00f3digo n\u00e3o funcionou. Verifique-o ou envie um novo c\u00f3digo para seu e-mail.', id: 'Kode itu tidak berhasil. Periksa atau kirim kode baru ke email Anda.' },
  pastor_wrong_password: { en: 'Invalid email or password', es: 'Correo o contrase\u00f1a no v\u00e1lidos', pt: 'E-mail ou senha inv\u00e1lidos', id: 'Email atau kata sandi tidak valid' },
  pastor_password_is_email: { en: 'Do not use your email as the password.', es: 'No uses tu correo como contrase\u00f1a.', pt: 'N\u00e3o use seu e-mail como senha.', id: 'Jangan gunakan email Anda sebagai kata sandi.' },
  pastor_password_too_long: { en: 'Password is too long.', es: 'La contrase\u00f1a es demasiado larga.', pt: 'A senha \u00e9 longa demais.', id: 'Kata sandi terlalu panjang.' },
  pastor_valid_email: { en: 'Enter a valid email.', es: 'Ingresa un correo v\u00e1lido.', pt: 'Digite um e-mail v\u00e1lido.', id: 'Masukkan email yang valid.' },
  pastor_type_email: { en: 'Type your work email.', es: 'Escribe tu correo de trabajo.', pt: 'Digite seu e-mail de trabalho.', id: 'Ketik email kerja Anda.' },
  pastor_code_sent_again: { en: 'Another code is on its way. Use the newest one; it lasts 30 minutes.', es: 'Va en camino otro c\u00f3digo. Usa el m\u00e1s reciente; dura 30 minutos.', pt: 'Outro c\u00f3digo est\u00e1 a caminho. Use o mais recente; ele vale por 30 minutos.', id: 'Kode baru sedang dikirim. Gunakan yang terbaru; berlaku 30 menit.' },
  pastor_staff_sign_in: { en: 'Staff sign-in', es: 'Inicio de sesi\u00f3n del equipo', pt: 'Entrada da equipe', id: 'Masuk staf' },
  pastor_staff_sign_in_hint: { en: 'Sign in to put Sunday’s sermon notes on the page people write in.', es: 'Inicia sesi\u00f3n para poner las notas del serm\u00f3n del domingo en la p\u00e1gina donde escribe la gente.', pt: 'Entre para colocar as notas do serm\u00e3o de domingo na p\u00e1gina onde as pessoas escrevem.', id: 'Masuk untuk menaruh catatan khotbah hari Minggu di halaman tempat orang menulis.' },
  pastor_staff_password_hint: { en: 'At least 10 characters. You will use it to sign in from now on.', es: 'Al menos 10 caracteres. Lo usar\u00e1s para iniciar sesi\u00f3n de ahora en adelante.', pt: 'Pelo menos 10 caracteres. Voc\u00ea usar\u00e1 esta senha para entrar daqui em diante.', id: 'Minimal 10 karakter. Anda akan menggunakannya untuk masuk mulai sekarang.' },
  staff_form_load_failed: { en: 'The form didn\'t load. Check your connection and try again.', es: 'El formulario no carg\u00f3. Revisa tu conexi\u00f3n e int\u00e9ntalo de nuevo.', pt: 'O formul\u00e1rio n\u00e3o carregou. Verifique sua conex\u00e3o e tente de novo.', id: 'Formulir tidak termuat. Periksa koneksi Anda dan coba lagi.' },
  staff_form_load_server: { en: 'The form didn\'t load. Try again in a minute.', es: 'El formulario no carg\u00f3. Int\u00e9ntalo de nuevo en un minuto.', pt: 'O formul\u00e1rio n\u00e3o carregou. Tente de novo em um minuto.', id: 'Formulir tidak termuat. Coba lagi sebentar lagi.' },
