  staff_wording_failed: { en: 'The wording didn\'t save. Check your connection and try again.', es: 'La redacci\u00f3n no se guard\u00f3. Revisa tu conexi\u00f3n e int\u00e9ntalo de nuevo.', pt: 'O texto n\u00e3o foi salvo. Verifique sua conex\u00e3o e tente de novo.', id: 'Kata-kata tidak tersimpan. Periksa koneksi Anda dan coba lagi.' },
