  study_sources_scripture_note: { en: 'Scripture text always comes from the Bible text itself. The AI never writes it.', es: 'El texto bíblico siempre proviene del texto bíblico mismo. La IA nunca lo escribe.', pt: 'O texto bíblico sempre vem do próprio texto bíblico. A IA nunca o escreve.', id: 'Teks Alkitab selalu berasal dari teks Alkitab itu sendiri. AI tidak pernah menulisnya.' },
  study_sources_failed: { en: 'Could not load the source list. It will be here next time.', es: 'No se pudo cargar la lista de fuentes. Estará aquí la próxima vez.', pt: 'Não foi possível carregar a lista de fontes. Estará aqui na próxima vez.', id: 'Tidak dapat memuat daftar sumber. Akan ada di sini lain kali.' },
  ai_pastor_framing: { en: 'A study assistant, not a ghostwriter. It finds the sources and shows you where they came from. You write the message.', es: 'Un asistente de estudio, no un escritor fantasma. Encuentra las fuentes y te muestra de dónde vienen. Tú escribes el mensaje.', pt: 'Um assistente de estudo, não um ghostwriter. Ele encontra as fontes e mostra de onde vieram. Você escreve a mensagem.', id: 'Asisten studi, bukan penulis bayangan. Ia menemukan sumbernya dan menunjukkan asalnya. Anda yang menulis pesannya.' },
  ai_teaser_new_title: { en: 'New here? Ask Bible AI anything', es: '¿Nuevo aquí? Pregúntale a Bible AI lo que sea', pt: 'Novo por aqui? Pergunte qualquer coisa ao Bible AI', id: 'Baru di sini? Tanyakan apa saja kepada Bible AI' },
  ai_teaser_new_sub: { en: "Not sure what this passage means? Tap here, it's like having a friend who knows the Bible really well.", es: '¿No sabes qué significa este pasaje? Toca aquí, es como tener un amigo que conoce muy bien la Biblia.', pt: 'Não sabe o que esta passagem significa? Toque aqui, é como ter um amigo que conhece muito bem a Bíblia.', id: 'Tidak yakin apa arti bagian ini? Ketuk di sini, seperti memiliki teman yang sangat mengenal Alkitab.' },
  ai_teaser_cong_title: { en: 'Go deeper with Bible AI', es: 'Profundiza con Bible AI', pt: 'Aprofunde-se com o Bible AI', id: 'Perdalam dengan Bible AI' },
  ai_teaser_cong_sub: { en: "Ask questions about today's reading, get historical context, or explore how it applies to your life.", es: 'Haz preguntas sobre la lectura de hoy, obtén contexto histórico o explora cómo se aplica a tu vida.', pt: 'Faça perguntas sobre a leitura de hoje, obtenha contexto histórico ou explore como ela se aplica à sua vida.', id: 'Ajukan pertanyaan tentang bacaan hari ini, dapatkan konteks sejarah, atau jelajahi bagaimana hal itu berlaku bagi hidup Anda.' },
  ai_teaser_comfort_title: { en: "Talk to Bible AI about what you're feeling", es: 'Habla con Bible AI sobre lo que sientes', pt: 'Converse com o Bible AI sobre o que você está sentindo', id: 'Bicarakan dengan Bible AI tentang apa yang Anda rasakan' },
  ai_teaser_comfort_sub: { en: 'You can ask anything, even the hard questions. Bible AI responds with compassion and Scripture.', es: 'Puedes preguntar cualquier cosa, incluso las preguntas difíciles. Bible AI responde con compasión y Escritura.', pt: 'Você pode perguntar qualquer coisa, até as perguntas difíceis. O Bible AI responde com compaixão e Escritura.', id: 'Anda dapat bertanya apa saja, bahkan pertanyaan sulit. Bible AI menjawab dengan belas kasih dan Firman.' },
  ai_teaser_study_title: { en: 'Explore the original languages', es: 'Explora los idiomas originales', pt: 'Explore os idiomas originais', id: 'Jelajahi bahasa asli' },
  ai_teaser_study_sub: { en: 'Greek and Hebrew word studies with the source named on every result, and the passages pointed to in the text.', es: 'Estudios de palabras en griego y hebreo con la fuente nombrada en cada resultado, y los pasajes señalados en el texto.', pt: 'Estudos de palavras em grego e hebraico com a fonte nomeada em cada resultado, e as passagens indicadas no texto.', id: 'Studi kata Yunani dan Ibrani dengan sumber yang disebutkan pada setiap hasil, dan bagian yang ditunjuk dalam teks.' },
  ai_teaser_pastor_title: { en: 'Bible AI for sermon prep', es: 'Bible AI para preparar sermones', pt: 'Bible AI para preparar sermões', id: 'Bible AI untuk persiapan khotbah' },
  ai_teaser_pastor_sub: { en: 'It finds the sources, names the licence, and points you at the passages. You write the message.', es: 'Encuentra las fuentes, nombra la licencia y te señala los pasajes. Tú escribes el mensaje.', pt: 'Ele encontra as fontes, nomeia a licença e indica as passagens. Você escreve a mensagem.', id: 'Menemukan sumber, menyebutkan lisensinya, dan menunjukkan bagian yang dimaksud. Anda yang menulis pesannya.' },
